notifyProfile = operation({
  label: "notifyProfile",
  input: readExecution,
  depends: { database, history: eventHistory, send: sendMail },
  run: async ({ database, history, send }, ctx) => {
    const [{ eq }, { execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./sync.schema.ts"),
    ]);
    const stored = (
      await database.select().from(execution).where(eq(execution.id, ctx.input.executionId))
    ).at(0);
    if (!stored?.notification) raise("RetryNotAvailable", {});
    if (stored.result) return { executionId: ctx.input.executionId };
    const sent = await send.settle({ rawInput: stored.notification });
    const result: Sync.Result =
      sent.status === "success"
        ? { kind: "complete", action: "profile", profileId: stored.stream }
        : {
            kind: "partial",
            action: "profile",
            profileId: stored.stream,
            notification: {
              kind: "failed",
              message: "Name saved; notification failed. You can retry the notification.",
            },
          };
    await database.transaction(async (tx) => {
      await history.lock(tx, stored.stream);
      const latest = await history.find(tx, ctx.input.executionId, stored.stream);
      if (latest?.result) return;
      await history.append(tx, stored.stream, ctx.input.executionId, [{ kind: "result", result }]);
    });
    return { executionId: ctx.input.executionId };
  },
})

eventHistory = resource({
  label: "sync.history",
  factory: async () => {
    const [{ eq, sql }, { stream, event, execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./sync.schema.ts"),
    ]);
    return {
      async lock(tx: Database.Transaction, id: string) {
        await tx.insert(stream).values({ id }).onConflictDoNothing();
        const row = (await tx.select().from(stream).where(eq(stream.id, id)).for("update")).at(0);
        if (!row) raise("StreamMissing", {});
        return row.revision;
      },
      async find(tx: Database.Transaction, id: string, owner: string) {
        const row = (await tx.select().from(execution).where(eq(execution.id, id))).at(0);
        if (row && row.stream !== owner) raise("StreamDenied", {});
        return row;
      },
      async append(
        tx: Database.Transaction,
        owner: string,
        executionId: string,
        payloads: Sync.Payload[],
      ) {
        const row = (
          await tx
            .update(stream)
            .set({ revision: sql`${stream.revision} + ${payloads.length}` })
            .where(eq(stream.id, owner))
            .returning()
        ).at(0);
        if (!row) raise("StreamMissing", {});
        await tx.insert(event).values(
          payloads.map((payload, offset) => ({
            stream: owner,
            revision: row.revision - payloads.length + offset + 1,
            executionId,
            payload,
          })),
        );
        for (const payload of payloads) {
          if (payload.kind === "result")
            await tx
              .update(execution)
              .set({ result: payload.result })
              .where(eq(execution.id, executionId));
        }
      },
    };
  },
})

notifications = resource({
  label: "sync.notifications",
  depends: { database },
  factory: async ({ database }, ctx) => {
    let revision = 0;
    let broken = false;
    let connection:
      | Promise<
          { kind: "connected"; close: () => Promise<void> } | { kind: "failed"; error: unknown }
        >
      | undefined;
    const watchers = new Set<() => void>();
    const wake = () => {
      revision += 1;
      for (const notify of watchers) notify();
    };
    ctx.defer(async () => {
      broken = true;
      wake();
      const current = await connection;
      if (current?.kind === "connected") await current.close();
    });
    return {
      async subscribe(disconnected?: () => void) {
        if (!connection || broken) {
          const previous = connection;
          broken = false;
          connection = (async () => {
            const old = await previous;
            if (old?.kind === "connected") await old.close();
            try {
              return {
                kind: "connected" as const,
                close: await database.listen(wake, () => {
                  broken = true;
                  wake();
                }),
              };
            } catch (error) {
              broken = true;
              return { kind: "failed" as const, error };
            }
          })();
        }
        const opened = connection;
        const connected = await opened;
        if (connected.kind === "failed") throw connected.error;
        if (broken || opened !== connection) raise("StreamDisconnected", {});
        let closed = false;
        let waiting: (() => void) | undefined;
        const notify = () => {
          if (broken || opened !== connection) disconnected?.();
          waiting?.();
        };
        watchers.add(notify);
        return {
          revision: () => revision,
          ended: () => closed || broken || opened !== connection,
          close() {
            closed = true;
            watchers.delete(notify);
            waiting?.();
          },
          async wait(after: number, signal: AbortSignal) {
            if (closed || broken || after !== revision || signal.aborted) return;
            const changed = Promise.withResolvers<void>();
            waiting = () => changed.resolve();
            signal.addEventListener("abort", notify, { once: true });
            try {
              await changed.promise;
            } finally {
              signal.removeEventListener("abort", notify);
              waiting = undefined;
            }
          },
        };
      },
    };
  },
})

